window.OLAYLAR_P0050 = [{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","bolge":4,"t":"1527-01-01","k":"siyaset","kapsam":"dis","etiket":["siyaset","diplomasi","konu-siyasi","konu-diplomasi"],"b":"Cetin Meclisi — Hırvat soyluları Mohaç'tan sonra Habsburg Ferdinand'ı Hırvatistan kralı seçti","yer_id":"Cetin (Cetingrad)","gun":"1 Ocak 1527","yer":"Cetin (Cetingrad), Hırvatistan Krallığı ve Una-Kupa serhaddi","kisiler":"Avusturya Arşidükü I. Ferdinand","d":"Mohaç'ta Macar-Hırvat kralı II. Lajos'un ölümüyle taht boşalınca Hırvat soyluları 31 Aralık 1526'da Cetin'de toplandı ve yılbaşı günü Avusturya arşidükü Ferdinand'ı kral ilan etti. TDV'nin ifadesiyle Hırvatlar bu seçimi Macar soylularından bağımsız olarak yaptılar; seçim belgesi, Osmanlı akınları karşısında hıristiyan devletten kopmamak gerekçesine dayanıyordu. Böylece Osmanlı Bosnası'na komşu Hırvat kaleleri Habsburg hânedanının tacına bağlandı; TDV'ye göre 1530'larda Habsburglar Hırvat sınır bölgesini düzenlemeye başladığında bu hattın ana merkezi Bihaç oldu.","kaynak":"hirvatistan · bihac + Hrvatski sabor, 'Sabor u Cetinu 1527. godine' (sabor.hr, resmî)"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1527-01-01","kesinlik":"yil","k":"fetih","kapsam":"ic","etiket":["toprak-kazanc","konu-askeri"],"b":"Bihaç'ın kısa süreli Osmanlı idaresi — Mohaç ve Yayça'nın düşüşünün ardından","gun":"1527 (Yayça'nın alınmasından sonra; süre 'kısa')","yer":"Bihaç (Bihke), Yayça (Jajce), Una serhaddi","yer_id":"Bihaç (Bihać)","kisiler":"","d":"Mohaç zaferinin ardından Osmanlılar Bosna'da Macar tampon bölgesinin merkezi Yayça'yı ve Banaluka'yı aldı. TDV'nin Bihaç maddesine göre Mohaç'ı izleyen yılda Yayça Kalesi'nin alınmasından sonra Bihaç kısa bir süre için yeniden Osmanlılar'ın idaresine geçti. Kalenin ne zaman ve nasıl elden çıktığı kaynakta yazmıyor; TDV yalnız 1530'larda Habsburgların Hırvat sınır bölgesini düzenlerken hıristiyanların elindeki Bihaç'ı ana merkez yaptığını belirtir. Bihaç'ın kalıcı fethi 1592'de Bosna Beylerbeyi Hasan Paşa'nın seferiyle gerçekleşecekti.","kaynak":"bihac · bosna-hersek"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","bolge":2,"t":"1814-01-28","k":"siyaset","kapsam":"dis","etiket":["siyaset","toprak","konu-siyasi","konu-askeri"],"b":"Dubrovnik'te Fransız idaresinin sonu — eski Osmanlı haraçgüzârı şehre Avusturya kuvvetleri girdi","gun":"28 Ocak 1814","yer":"Dubrovnik (Ragusa), Gruž","yer_id":"Dubrovnik","kisiler":"Avusturya general-majörü Milutinović","d":"TDV'ye göre 1365'ten beri Osmanlı himayesinde bulunan Dubrovnik Cumhuriyeti'ne Fransızlar 27 Mayıs 1806'da şehri zaptederek son vermişti. 1813-1814 kışında şehir halkı Fransızlara karşı ayaklandı; 3 Ocak 1814'te iki Hırvat taburuyla Gruž'a gelen Avusturya general-majörü Milutinović garnizonu kuşattı; dört günlük bombardımanın ardından Fransız garnizonu generale elçi gönderdi. 28 Ocak şafağında Avusturya ve İngiliz birlikleri Gruž'dan şehre yürüdü; 31 Ocak'ta bölgede geçici Avusturya idaresi işlemeye başladı. Şehrin Avusturya topraklarına katılışı 1815 Viyana Kongresi'nde kesinleşti.","kaynak":"dubrovnik + F. Bona, Kolo 2/2008 (Matica hrvatska) + Državni arhiv u Dubrovniku HR-DADU-310"},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","bolge":4,"t":"1882-03-06","k":"siyaset","kapsam":"dis","etiket":["siyaset","konu-siyasi"],"b":"Sırbistan Krallığı'nın ilânı — eski Osmanlı tâbii prenslik krallığa dönüştü","gun":"6 Mart 1882 (Sırp takvimiyle 22 Şubat)","yer":"Belgrad, Niş, Semendire, Kragujevac","yer_id":"Belgrad","kisiler":"Kral I. Milan (Milan Obrenoviç)","d":"1878'de bağımsızlığını kazanan ve aynı yıl Osmanlı elindeki Niş'i de alan Sırbistan Prensliği, Milan Obrenoviç döneminde krallığa dönüştürüldü. Belgrad'da çıkarılan kanunun ilk maddesiyle prenslik Sırbistan Krallığı ilan edildi ve Prens Milan I. Milan adıyla kral oldu; kanun aynı gün resmî Srpske novine gazetesinde yayımlandı. Böylece 1878'e kadar Osmanlı'ya bağlı bir prenslik olan Sırbistan, Balkanlar'da krallık unvanıyla yerini aldı. Bu ilânla Sırbistan Prensliği'nin tamamı (Belgrad, Niş, Yagodina, İvranye, Leskofça, Ürküp, Şehirköy vd.) Sırbistan Krallığı oldu.","kaynak":"sirbistan · nis + Zakon o proglašenju Knjažestva Srbije za Kraljevinu, Srpske novine 41 (22.II.1882) · Yer teyidi (DUNYA-1102 D(b), 3 Kasım 2026): TDV İslâm Ansiklopedisi, 'Sırbistan' (islamansiklopedisi.org.tr/sirbistan)"},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","t":"1920-07-01","k":"siyaset","kapsam":"ic","etiket":["siyaset","konu-siyasi"],"b":"Filistin'de İngiliz sivil manda idaresi kuruldu — Osmanlı'dan alınan topraklarda askerî yönetimin sonu","gun":"1 Temmuz 1920","yer":"Kudüs, Gazze, Yafa, Akkâ, Nablus","yer_id":"Kudüs","kisiler":"Yüksek Komiser Herbert Samuel","d":"1917'de General Allenby'nin Gazze'yi ve ardından Kudüs'ü almasıyla Filistin'de dört yüz yıllık Osmanlı hâkimiyeti sona ermiş, Kudüs 1917-1920 arasında İngiliz askerî yönetiminde kalmıştı. 1920 San Remo Konferansı Filistin'i İngiliz mandasına verdi; İngiltere Temmuz 1920'den itibaren bölgede sivil bir manda yönetimi kurarak ülkeyi bir yüksek komiser aracılığıyla yönetmeye başladı. Sivil idarenin başında yüksek komiser Herbert Samuel vardı. Aynı yıl başlayan Arap ayaklanmaları ve yahudi-Arap çatışmaları manda döneminin bütününe damga vuracaktı. Bu olayla Tiberya (Filistin) İngiliz sivil manda idaresine geçti.","kaynak":"filistin · kudus · gazze + Interim Report on the Civil Administration of Palestine, 1st July 1920–30th June 1921 (HMSO 1921) · Yer teyidi (DUNYA-1102 D(b), 3 Kasım 2026): TDV İslâm Ansiklopedisi, 'Filistin' (islamansiklopedisi.org.tr/filistin) — açıldı, okundu"},{"onem":4,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1922-03-15","k":"siyaset","kapsam":"ic","etiket":["siyaset","konu-siyasi"],"b":"Mısır Krallığı ilan edildi — Sultan Ahmed Fuâd kral unvanını aldı","gun":"15 Mart 1922","yer":"Kahire, İskenderiye","yer_id":"Kahire","kisiler":"Sultan (Kral) Ahmed Fuâd","d":"İngiltere 18 Aralık 1914'te Osmanlı Devleti'nin Mısır üzerindeki hükümranlık haklarını tek taraflı olarak kaldırıp ülkeyi himayesine almıştı. Savaş sonrasında İngiltere ile Mısır arasındaki müzakerelerden sonuç çıkmayınca İngiltere 28 Şubat 1922'de yine tek taraflı bir bildiriyle Mısır'ı bağımsız devlet ilan etti. Sultan Ahmed Fuâd 15 Mart 1922'de kral (melik) unvanını aldı ve Mısır'da monarşi ilan edildi. TDV bu bağımsızlığı şeklî sayar; krallık düzeninin anayasası 19 Nisan 1923'te yürürlüğe girecekti.","kaynak":"misir"}];

