window.OLAYLAR_P0053 = [{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1624-01-01","kesinlik":"yil","k":"kayip","kapsam":"ic","etiket":["toprak-kayip","savas","konu-askeri"],"b":"Musul ve Kerkük'ün Safevî eline geçmesi — Bağdat'ın düşüşünün ardından","gun":"1033 (1623-24) — kaynak gün vermiyor","yer":"Musul, Kerkük","yer_id":"Musul","kisiler":"Şah Abbas, Karçakay Han, Çerkez Ahmed Paşa, Kāsım Han, Sipahi Küçük Ahmed","d":"Bekir Subaşı isyanıyla başlayan olaylar sonunda Bağdat'ı ele geçiren Şah Abbas, kumandanı Karçakay Han'ı kuvvetleriyle Musul ve Kerkük üzerine gönderdi. Musul Valisi Çerkez Ahmed Paşa şehri birkaç gün savunabildi; Kerkük gibi Musul da İran hâkimiyetine geçti ve valiliğe Kāsım Han getirildi. Hâfız Ahmed Paşa'nın öncü kuvvetine kumanda eden Sipahi Küçük Ahmed Musul önünde görününce Kāsım Han şehri bırakıp Bağdat'a çekildi, fakat Şah Abbas'ın karşı harekâtıyla Musul 1624'te yeniden Safevîlerin eline geçti.","kaynak":"musul--irak · hafiz-ahmed-pasa · kerkuk + Remzi Kılıç, Türk Kültürü XXXIX/460 (2001), ss. 479-493"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1625-01-01","kesinlik":"yil","k":"fetih","kapsam":"ic","etiket":["toprak-kazanc","savas","konu-askeri"],"b":"Musul'un Safevîlerden kurtarılması — Hâfız Ahmed Paşa'nın Bağdat seferi","gun":"1035 (1625) — ordu eylül başında Musul'a vardı; gün yok","yer":"Musul, Kerkük, Altınköprü","yer_id":"Musul","kisiler":"Hâfız Ahmed Paşa, Çerkez Hasan Paşa","d":"IV. Murad, Vezîriâzam Hâfız Ahmed Paşa kumandasındaki orduyu Bağdat üzerine gönderdi. Ordu Diyarbekir civarındayken Altınköprü'de toplanan İran taraftarlarını Karaman Beylerbeyi Çerkez Hasan'ın öncü kuvveti Kerkük'e kadar kovaladı ve Kerkük de dahil bölgeyi kontrol altına aldı; Safevîler Musul'u bu defa da uzun süre elde tutamadı. Hâfız Ahmed Paşa eylül başında önce Musul'a, ardından Kerkük'e vardı ve 13 Kasım 1625'te Bağdat'ı kuşattı; kuşatma sonuçsuz kaldı ve Bağdat Safevî elinde kaldı. TDV'nin Kerkük maddesi ise şehrin Safevîlerden geri alınışını 1630'a, Hüsrev Paşa'ya bağlar.","kaynak":"musul--irak · hafiz-ahmed-pasa · kerkuk + Remzi Kılıç, Türk Kültürü XXXIX/460 (2001)"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1630-03-16","k":"fetih","kapsam":"ic","etiket":["toprak-kazanc","savas","konu-askeri"],"b":"Hüsrev Paşa'nın Şehrizor'da Gülanber Kalesi'ni yeniden kurması — Şehrizor beylerbeyiliği","gun":"16 Mart 1630","yer":"Gülanber, Şehrizor","yer_id":"Şehrizor","kisiler":"Boşnak Hüsrev Paşa, Arnavud Mustafa Paşa","d":"Bağdat seferine çıkan Sadrazam Hüsrev Paşa, şiddetli yağışlar yüzünden Musul'da uzun süre kaldıktan sonra Şehrizor'a yöneldi. Şah Abbas'ın istilâsında onun emriyle yıktırılmış olan Gülanber Kalesi'nin yeniden inşasına başlandı; Şehrizor tekrar beylerbeyilik merkezi yapıldı ve kaleye Arnavud Mustafa Paşa beylerbeyi olarak bırakıldı. Hüsrev Paşa bölgedeki aşiretleri itaat altına aldı, Mihriban Kalesi'ni ele geçirdi ve 5 Mayıs 1630'da bu kale yakınında Safevî ordusuna ağır kayıplar verdirdi.","kaynak":"sehrizor · murad-iv + Remzi Kılıç, Türk Kültürü XXXIX/460 (2001), ss. 479-493"}];

