window.OLAYLAR_P0056 = [{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","tur":"savas","t":"1739-08-28","k":"kayip","kapsam":"ic","etiket":["savas","toprak-kayip","konu-askeri"],"b":"Stavuçani yenilgisi ve Hotin'in Ruslara teslimi (1736-1739 Osmanlı-Rus Savaşı)","gun":"28 Ağustos 1739 (Jülyen 17 Ağustos)","yer":"Stavuçani, Hotin yakını — Boğdan","yer_id":"Hotin","yer_kon":[48.389,26.406],"kisiler":"Mareşal Münnich (Minih), Serasker Veli Paşa","d":"1739 seferinde Rus ana ordusu Mareşal Münnich komutasında Lehistan toprağından geçerek Boğdan'a girdi ve Hotin yakınındaki Stavuçani'de Serasker Veli Paşa'nın ordusunu ağır bir yenilgiye uğrattı. Bu savaşın hemen ardından Hotin kalesi Ruslara teslim oldu ve Rus kuvvetleri Eylül başında Yaş'a girdi. Ancak Avusturya'nın ayrı barış yapması üzerine savaş, aynı ay imzalanan Belgrad Antlaşması ile sona erdi.","kaynak":"TDV İslâm Ansiklopedisi, «HOTİN» https://islamansiklopedisi.org.tr/hotin — «kale 1739’da Mareşal Münnich idaresindeki Rus ordusunun eline geçti» [yalnız yıl teyitli; gün teyitsiz] ; ESBE «Турецкие войны России» (ru.wikisource): '17 августа русское войско встретилось с Т.' · 'Вслед за ставучанской битвой пал и Хотин'","duygu":["⚔️"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","tur":"savas","t":"1769-01-01","k":"savas","kapsam":"ic","etiket":["savas","konu-askeri"],"b":"Rus ordusunun Dinyester'i geçerek Boğdan'a girmesi (1768-1774 Osmanlı-Rus Savaşı)","gun":"1769","yer":"Dinyester, Hotin önleri — Boğdan","yer_id":"Hotin","kisiler":"Prens A. M. Golitsin","d":"Savaş ilanından yaklaşık altı ay sonra Rus ana ordusu Prens Golitsin komutasında Podolya'da toplandı. Boğdan metropoliti Dositey'in Moldova'yı Rus himayesine alma çağrısı üzerine Golitsin Dinyester'i geçti ve Yaş'a yürümeden önce Hotin'i almayı denedi. Bu ilk deneme başarısız oldu, ordu erzak sıkıntısı yüzünden Podolya'ya geri döndü; Hotin ancak Eylül 1769'da düştü.","kaynak":"TDV İslâm Ansiklopedisi, «HOTİN» https://islamansiklopedisi.org.tr/hotin — «1769’da Osmanlı-Rus savaşları sırasında Prens Aleksandr Mihayloviç Golitsın tarafından zaptedildi» ; ESBE «Турецкие войны России» (ru.wikisource): '15 апреля он перешел Днестр, но перед движением в Яссы попытался овладеть Хотиным'","duygu":["⚔️"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","tur":"savas","t":"1788-01-01","k":"savas","kapsam":"ic","etiket":["savas","konu-askeri"],"b":"Rus Ukrayna ordusunun Mogilev'de Dinyester'i geçip Boğdan'a girmesi (1787-1792 Osmanlı-Rus Savaşı)","gun":"1788","yer":"Mogilev (Mohyliv-Podilskyi), Dinyester — Boğdan'ın kuzeyi","yer_kon":[48.446,27.798],"kisiler":"Mareşal Rumyantsev","d":"1787'de Osmanlı'nın savaş ilanıyla başlayan savaşta Rusya iki ordu kurdu: Potemkin'in ordusu Özi'yi kuşatırken Rumyantsev'in Ukrayna ordusu Dinyester ile Bug arasında Bender'i tehdit edecek ve Avusturya ile bağlantıyı tutacaktı. Rumyantsev bir kolu Hotin'i kuşatan Avusturyalılara destek için ayırdı, ana kuvvetleriyle Mogilev'de Dinyester'i geçerek Boğdan'a girdi. İsmail'e ve Tuna'ya uzanacak Rus harekâtının Boğdan ayağı böylece başladı.","kaynak":"TDV İslâm Ansiklopedisi, «HOTİN» https://islamansiklopedisi.org.tr/hotin — «1788-1791 savaşı sırasında Avusturya ve Rusya ortak kuvvetleri tarafından kuşatıldı» ; ESBE «Турецкие войны России» (ru.wikisource): 'главные же силы Украинской армии 20 июня перешли через Днестр у Могилева'","duygu":["⚔️"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","tur":"savas","t":"1806-11-23","k":"savas","kapsam":"ic","etiket":["savas","toprak-kayip","konu-askeri"],"b":"Rus ordusunun savaş ilan edilmeden Dinyester'i geçip Memleketeyn'i işgale başlaması (1806-1812 Osmanlı-Rus Savaşı)","gun":"23 Kasım 1806 (Jülyen 11 Kasım)","yer":"Dinyester hattı — Hotin, Bender, Akkirman, Kili","yer_id":"Hotin","kisiler":"General Michelson (Mihelson)","d":"Ekim 1806'da General Michelson'a Boğdan ve Eflak'ı işgal etme emri verildi; savaş henüz resmen ilan edilmemişti. Rus kuvvetleri Dinyester'i geçmeye başladı ve Hotin, Bender, Akkirman ile Kili kalelerinin komutanları kalelerini çarpışmadan teslim etti. Yalnız İsmail muhafızı Rus telkinlerine boyun eğmedi. Bâbıâli'nin savaş ilanı bu işgalden sonra geldi.","kaynak":"TDV İslâm Ansiklopedisi, «HOTİN» https://islamansiklopedisi.org.tr/hotin — «Hotin son olarak 1806’da Ruslar’ın işgaline uğradı» [yalnız yıl teyitli; gün teyitsiz] ; ESBE «Турецкие войны России» (ru.wikisource): 'хотя война формально и не была еще объявлена' · 'коменданты крепостей Хотин, Бендеры, Акерман и Килия уступили их без боя'","duygu":["⚔️"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1806-11-30","k":"kayip","kapsam":"ic","etiket":["savas","toprak-kayip","konu-askeri"],"b":"Akkirman'ın Ruslar tarafından ele geçirilmesi (1806)","gun":"30 Kasım 1806","yer":"Akkirman, Dinyester ağzı","yer_id":"Akkirman","kisiler":"Prens Kantakuzino","d":"Rus ordusunun savaş ilan edilmeden Dinyester'i geçmesinden bir hafta sonra Akkirman, Prens Kantakuzino'nun kuvvetlerince ele geçirildi; şehirdeki Tatarlar şehri terk etti. Akkirman 1812 Bükreş Antlaşması'yla Besarabya ile birlikte Rusya'ya bırakıldı.","kaynak":"akkirman (TDV): '30 Kasım 1806 tarihinde Rus Prensi Kantakuzino tarafından ele geçirilmesi üzerine'","duygu":["😔"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1806-12-25","k":"kayip","kapsam":"ic","etiket":["savas","toprak-kayip","konu-askeri"],"b":"Miloradoviç'in Bükreş'e girmesi — Eflak'ın Rus işgali","gun":"25 Aralık 1806 (Jülyen 13 Aralık)","yer":"Bükreş, Eflak","yer_id":"Bükreş","kisiler":"General Miloradoviç, Rusçuk muhafızı Mustafa Paşa","d":"Rus ordusu Boğdan'a girdiğinde Rusçuk muhafızı Mustafa Paşa Bükreş'e bir kuvvet gönderdi ve bu kuvvet şehri tuttu. General Miloradoviç'in müfrezesi onları şehirden çıkardı; Osmanlı kuvveti Yergöğü'ne çekildi. Bükreş bu tarihten 1812 Bükreş Antlaşması'na kadar Rus işgalinde kaldı.","kaynak":"ESBE «Турецкие войны России» (ru.wikisource): 'рущукский комендант Мустафа-паша выслал отряд войск к Букаресту' · '13 декабря были вытеснены'","duygu":["😔"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1810-06-10","k":"kayip","kapsam":"ic","etiket":["savas","toprak-kayip","konu-askeri"],"b":"Silistre'nin Ruslara teslimi","gun":"10 Haziran 1810 (Jülyen 29 Mayıs)","yer":"Silistre, Tuna'nın sağ yakası","yer_id":"Silistre","kisiler":"General N. M. Kamenski","d":"1809 sonbaharında Bagration'un kuşatmasına dayanan Silistre, 1810 seferinde başkumandan Kamenski'nin emriyle yeniden kuşatıldı. Mayıs sonunda başlayan kuşatma işleri birkaç gün sürdü ve kale, garnizonun serbestçe çıkması şartıyla teslim oldu. Aynı günlerde Pazarcık fırtınayla alındı, Hezargrad düştü. Ruslar Silistre'yi bir yıl tuttu; 1811 baharında Kutuzov surları havaya uçurup kaleyi bıraktı.","kaynak":"ESBE «Силистрия» (ru.wikisource): '29-го мая крепость была сдана на условии свободного…' · ESBE «Турецкие войны России»: '30 сдалась Силистрия' · TDV silistre","duygu":["😔"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1810-10-01","k":"kayip","kapsam":"ic","etiket":["savas","toprak-kayip","konu-askeri"],"b":"Niğbolu ve Kule'nin (Turnu) direnmeden Ruslara teslimi","gun":"Ekim 1810","kesinlik":"ay","yer":"Niğbolu ve Kule (Turnu Măgurele), Tuna boyu","yer_id":"Niğbolu","kisiler":"General N. M. Kamenski, General Kutuzov","d":"Rusçuk ve Yergöğü'nün teslim olmasının ardından başkumandan Kamenski Sırbistan sınırına kadar Tuna kalelerini almak için nehir boyunca batıya yürüdü. Niğbolu ve karşı yakadaki Kule direnmeden teslim oldu; Rus müfrezeleri Plevne, Lofça ve Selvi'yi alıp tahkimatını yıktı. Ruslar Niğbolu'yu altı ay tuttu ve 1811 Nisanında kaleyi havaya uçurarak bıraktı.","kaynak":"TDV nigbolu: '1810 yılı Ekim ayında … Kutuzov'un kuvvetleri tarafından ele geçirildi' · ESBE «Турецкие войны России»: 'Никополь и Турно сдались без сопротивления'","duygu":["😔"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","tur":"savas","t":"1811-07-04","k":"savas","kapsam":"ic","etiket":["savas","toprak-kazanc","konu-askeri"],"b":"Rusçuk Muharebesi ve Kutuzov'un Rusçuk'u yıkıp Tuna'nın sol yakasına çekilmesi","gun":"4 Temmuz 1811 (Jülyen 22 Haziran) — muharebe; çekilişin günü kaynakta yok","yer":"Rusçuk, Tuna'nın sağ yakası","yer_id":"Rusçuk","kisiler":"General Kutuzov, Sadrazam Ahmed Paşa","d":"Haziran başında Şumnu'dan çıkan sadrazam Rusçuk önünde Rus ordusuna saldırdı, yenilerek güneydeki tahkimli mevziine çekildi. Kutuzov kazandığı bu muharebeye rağmen Rusçuk'ta kalmayı tehlikeli buldu; kalenin istihkâmlarını yıktırdı ve bütün kuvvetlerini Tuna'nın sol yakasına geçirdi. Sadrazam boşaltılan Rusçuk'u yeniden aldı. Böylece Kaminski'nin kanlı bir kuşatmanın ardından 26 Eylül 1810'da teslim aldığı şehirde Rus tutuşu dokuz ay sürmüş oldu. TDV'nin kaydına göre Kutuzov ayrılmadan önce şehir etrafındaki istihkâmın ve ortaçağ kalesinin havaya uçurulmasını emretti; çıkan yangında 1810'da şehirde bulunan otuz sekiz caminin on ikisi ve sekiz mescidden ikisi bütünüyle yıkıldı. Aynı yılın sonbaharında Osmanlı ordusunun Tuna'yı geçmesi Slobozia kuşatmasıyla sonuçlanacaktı.","kaynak":"ESBE «Турецкие войны России» (ru.wikisource): 'Кутузов … разрушив его укрепления, переправил все войска на левый берег' · 'По отступлении Кутузова на левый берег визирь занял Рущук' · TDV ruscuk","duygu":["⚔️"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","tur":"savas","t":"1828-05-07","k":"savas","kapsam":"ic","etiket":["savas","toprak-kayip","konu-askeri"],"b":"Rus 6. Piyade Kolordusunun Prut'u geçip Memleketeyn'e girmesi (1828-1829 Osmanlı-Rus Savaşı)","gun":"7 Mayıs 1828 (Jülyen 25 Nisan)","yer":"Prut — Boğdan ve Eflak","yer_id":"Yaş","kisiler":"Mareşal Wittgenstein, General Geismar","d":"Rusya'nın savaş ilanının ardından Mareşal Wittgenstein'ın ordusu harekâta geçti. 6. Piyade Kolordusu Prut'u geçerek Boğdan ve Eflak'a girdi, öncüsü General Geismar komutasında Küçük Eflak'a yöneldi. Birkaç gün sonra 7. Kolordu İbrail'i kuşattı; 3. Kolordu ise İsmail ile Reni arasında Tuna'yı geçmeye hazırlandı. Memleketeyn 1834'e kadar Rus işgalinde kalacaktı.","kaynak":"TDV İslâm Ansiklopedisi, «EDİRNE ANTLAŞMASI» https://islamansiklopedisi.org.tr/edirne-antlasmasi — «Rusya ise … savaş açmıştı (26 Nisan 1828). … Ruslar Boğdan’a girdikleri» [yalnız yıl teyitli; gün teyitsiz] ; ESBE «Турецкие войны России» (ru.wikisource): '25 апр. 6-й пех. корпус вступил в княжества' · '1 мая 7-й пех. корпус обложил крепость Браилов'","duygu":["⚔️"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1829-06-30","k":"kayip","kapsam":"ic","etiket":["savas","toprak-kayip","konu-askeri"],"b":"Silistre'nin Dibiç'e teslimi — 1836'ya kadar sürecek Rus işgali","gun":"30 Haziran 1829 (Jülyen 18 Haziran)","yer":"Silistre, Tuna'nın sağ yakası","yer_id":"Silistre","kisiler":"General Dibiç (Diebitsch), General Schilder","d":"1829 seferinin başında yeni Rus başkumandanı Dibiç ilk hedef olarak Silistre'yi seçti. General Schilder'in yönettiği kuşatma işlerine garnizon inatla karşı koydu; Dibiç kuvvetlerinin bir kısmını kuşatmada bırakıp sadrazamın arkasına yürüdü. Kuşatma sürdü ve kale teslim oldu. Ruslar Silistre'yi savaş bittikten sonra da 1836'ya kadar ellerinde tuttular.","kaynak":"ESBE «Турецкие войны России» (ru.wikisource): 'осада Силистрии шла успешно, и 18 июня крепость эта сдалась' · ESBE «Силистрия»: 'В 1829 г. новый главнокомандующий, ген. Дибич, избрал первым предметом своих действий С.' · TDV silistre","duygu":["😔"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1836-01-01","k":"siyaset","kapsam":"ic","etiket":["toprak-kazanc","konu-diplomasi"],"b":"Rusların Silistre'yi boşaltması","gun":"1836","kesinlik":"yil","yer":"Silistre","yer_id":"Silistre","d":"1829 Edirne Antlaşması'ndan sonra Ruslar Silistre'yi boşaltmadı ve kaleyi 1836'ya kadar elde tuttu. Rus askerlerinin çekilmesinden sonra vali Selim Paşa yarısı yıkılmış şehrin ortasına büyük, tek kubbeli bir cami yaptırdı.","kaynak":"TDV silistre: 'Ruslar 1836'ya kadar Silistre'yi ellerinde tuttular' · 'Rus askerlerinin şehri boşaltmasının ardından Vali Selim Paşa'","duygu":["📌"]},{"onem":4,"dunya":3,"bolge_onem":4,"puan_s":"v2","tur":"savas","t":"1853-07-03","k":"savas","kapsam":"ic","etiket":["savas","konu-askeri"],"b":"Rus ordusunun Prut'u geçip Memleketeyn'i (Eflak-Boğdan) işgale başlaması — Kırım Savaşı'na giden yol","gun":"3 Temmuz 1853 (Jülyen 21 Haziran)","yer":"Prut — Besarabya ile Boğdan arasındaki sınır","yer_id":"Yaş","kisiler":"Prens Mihail Gorçakov, General Anrep-Elmpt, I. Nikola","d":"Kudüs'teki kutsal yerler anlaşmazlığında Menşikov'un istekleri Bâbıâli'ce reddedilince Çar I. Nikola, Osmanlı'ya bağlı Tuna beyliklerinin 'Türkiye haklı taleplerimizi karşılayana dek rehin olarak' işgalini emretti. Prens Gorçakov komutasındaki ordunun öncüsü Prut'u geçti ve on iki gün sonra Bükreş'e girdi; arkasından ana kuvvet üç kol hâlinde beyliklere yayıldı. Savaş ilan edilmeden yapılan bu işgal Avrupa'da diplomatik krize, Ekim 1853'te de Osmanlı'nın savaş ilanına yol açtı; Ruslar beylikleri ancak 1854 yazında Avusturya'nın baskısıyla boşalttı.","kaynak":"Военная энциклопедия (Sytin, 1911-1915), «Восточная война 1853—56 гг.» (ru.wikisource): '21 июня авангард армии … переправился через Прут и 3 июля вступил в Бухарест' · ESBE «Восточная война»: 'приказал русским войскам (80 тыс.) занять … дунайские княжества … «в залог»'","duygu":["⚔️"]}];

