window.OLAYLAR_P0057 = [{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1919-01-23","k":"kayip","etiket":["isgal","konu-askeri"],"b":"Eskişehir'in İngilizlerce işgali","gun":"23 Ocak 1919","yer":"Eskişehir","yer_id":"Eskişehir","kisiler":"","d":"Mondros Mütarekesi'nin ardından İtilaf devletleri Anadolu'nun demiryolu kavşaklarını denetim altına almaya başladı. TDV'nin Eskişehir maddesine göre şehir 23 Ocak 1919'da İngilizler tarafından işgal edildi. İngiliz birlikleri Eskişehir'i 20 Mart 1920'de boşalttı.","kaynak":"eskisehir"},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1919-05-11","k":"kayip","etiket":["isgal","konu-askeri","konu-diplomasi"],"b":"İtalyanların Güneybatı Anadolu kıyılarına çıkışı — Marmaris, Bodrum, Kuşadası","gun":"5-13 Mayıs 1919","yer":"Bodrum, Marmaris, Kuşadası, Fethiye","yer_id":"Bodrum","kisiler":"","d":"Paris Barış Konferansı'nda müttefiklerinin Yunan yanlısı tutumunu protesto ederek konferanstan çekilen İtalya, Antalya'dan sonra güneybatı kıyılarına asker çıkardı. TDV'ye göre 5 Mayıs'ta Marmaris, 11 Mayıs'ta Bodrum, 13 Mayıs'ta Kuşadası İtalyan işgaline uğradı. Aynı günlerde Yunanlılar da Fethiye'ye çıktı; iki devletin Batı Anadolu üzerindeki rekabeti İzmir'in işgaline giden yolu hazırladı.","kaynak":"bodrum · sevr-antlasmasi"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1919-05-26","k":"kayip","etiket":["isgal","konu-askeri"],"b":"Yunan kuvvetlerinin Manisa ve Aydın'a girişi","gun":"26-27 Mayıs 1919","yer":"Manisa, Aydın","yer_id":"Manisa","kisiler":"","d":"İzmir'e 15 Mayıs'ta çıkan Yunan ordusu kısa sürede iç kesimlere yayıldı. TDV'nin Manisa maddesine göre Yunan kuvvetleri 26 Mayıs 1919'da şehre girdi; Aydın maddesine göre Aydın ertesi gün, 27 Mayıs'ta işgal edildi. Manisa işgali 1922 Eylülüne kadar sürecekti.","kaynak":"manisa · aydin"},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","kapsam":"ic","t":"1919-06-28","k":"kayip","etiket":["isgal","konu-askeri"],"b":"Burdur'un İtalyan işgali — Isparta'ya yönelen bölüğün geri çekilişi","gun":"28 Haziran 1919","yer":"Burdur, Isparta","yer_id":"Burdur","kisiler":"","d":"Antalya'yı işgal eden İtalyanlar iç bölgelere doğru ilerledi. TDV'nin Isparta maddesine göre İtalyan birlikleri 28 Haziran'da Burdur'u işgal etti ve 15 Ağustos'ta bir bölük askerle Isparta'ya yöneldi. Isparta halkının silahları teslim teklifini reddedip direneceğini bildirmesi üzerine İtalyanlar ertesi gün geri çekildi.","kaynak":"isparta · burdur"},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","tur":"savas","kapsam":"ic","t":"1919-06-30","k":"savas","etiket":["savas","kurtulus","isgal","konu-askeri"],"b":"Aydın'ın kısa süreli kurtarılışı ve 4 Temmuz'da yeniden işgali","gun":"30 Haziran – 4 Temmuz 1919","yer":"Aydın","yer_id":"Aydın","kisiler":"","d":"Yunan işgaline karşı Ödemiş, Nazilli ve Aydın çevresinde millî kuvvetler teşkilatlandı. TDV'nin Aydın maddesine göre 27 Mayıs 1919'da işgal edilen şehir 30 Haziran'da kısa bir süre için kurtarıldı, ancak 4 Temmuz'da yeniden Yunan işgaline uğradı. Şehir bundan sonra 7 Eylül 1922'ye kadar işgal altında kaldı.","kaynak":"aydin · milli-mucadele"},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","kapsam":"ic","t":"1919-07-23","k":"kayip","etiket":["isgal","konu-askeri"],"b":"Muğla'nın İtalyan işgali","gun":"23 Temmuz 1919","yer":"Muğla","yer_id":"Muğla","kisiler":"","d":"İtalya, güneybatı kıyılarındaki işgalini iç kesimlere doğru genişletti. TDV'nin Muğla maddesine göre şehir 23 Temmuz 1919'da İtalyan işgaline uğradı. Muğla'nın işgali 5 Temmuz 1921'e kadar sürdü.","kaynak":"mugla"},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","kapsam":"ic","t":"1920-03-20","k":"siyaset","etiket":["isgal","konu-askeri"],"b":"İngilizlerin Eskişehir'i boşaltması","gun":"20 Mart 1920","yer":"Eskişehir","yer_id":"Eskişehir","kisiler":"","d":"Ocak 1919'dan beri İngiliz işgalinde bulunan Eskişehir, TDV'nin Eskişehir maddesine göre 20 Mart 1920'de İngilizler tarafından boşaltıldı. Şehir birkaç ay sonra, Haziran 1920'de, TBMM'nin kurduğu Garp Cephesi'nin merkezi oldu.","kaynak":"eskisehir"},{"onem":4,"dunya":2,"bolge_onem":3,"puan_s":"v2","tur":"savas","kapsam":"ic","t":"1920-06-22","k":"savas","etiket":["savas","isgal","konu-askeri"],"b":"Yunan yaz taarruzu — Akhisar, Soma, Balıkesir ve Alaşehir'in işgali","gun":"22 Haziran – 3 Temmuz 1920","yer":"Akhisar, Kırkağaç, Soma, Balıkesir, Alaşehir, Nazilli","yer_id":"Balıkesir","kisiler":"","d":"Müttefiklerin Yunan ordusuna Milne hattını aşarak ilerleme izni vermesiyle Batı Anadolu'da büyük bir Yunan taarruzu başladı. TDV'nin Millî Mücadele maddesine göre 22 Haziran'da üç koldan harekete geçen Yunan birlikleri Akhisar, Kırkağaç, Soma ve Balıkesir'i ele geçirdi. Güneyde 26 Haziran'da Alaşehir, 3 Temmuz'da Nazilli işgal edildi.","kaynak":"milli-mucadele · alasehir"},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1920-07-08","k":"kayip","etiket":["isgal","konu-askeri"],"b":"Bursa'nın Yunan işgali","gun":"8 Temmuz 1920","yer":"Bursa","yer_id":"Bursa","kisiler":"","d":"Yaz taarruzunun kuzey kolu Balıkesir'den sonra Marmara'ya yöneldi. TDV'nin Bursa ve Millî Mücadele maddelerine göre Bursa 8 Temmuz 1920'de Yunan işgaline uğradı. İlk Osmanlı hükümdarlarının türbelerine yapılan saygısızlıklar ülke çapında büyük tepki doğurdu.","kaynak":"bursa · milli-mucadele"},{"onem":4,"dunya":2,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1920-07-20","k":"kayip","etiket":["isgal","konu-askeri"],"b":"Yunan ordusunun Doğu Trakya'yı işgali — Edirne ve Kırklareli","gun":"20-26 Temmuz 1920","yer":"Edirne, Kırklareli, Tekirdağ","yer_id":"Edirne","kisiler":"","d":"Yunanistan, Sevr Antlaşması imzalanmadan önce Doğu Trakya'yı da fiilen ele geçirmeye girişti. TDV'nin Millî Mücadele maddesine göre Yunan ordusu 20 Temmuz'da bütün Trakya'yı ele geçirdi; bu gelişme İstanbul'da padişahı iki gün sonra Saltanat Şûrası'nı toplamaya yöneltti. Kırklareli 26 Temmuz'da işgale uğradı, Edirne de aynı ay Yunan idaresine girdi.","kaynak":"milli-mucadele · kirklareli · edirne"},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","kapsam":"dis","bolge":3,"t":"1920-07-28","k":"siyaset","etiket":["isgal","konu-askeri","konu-siyasi"],"b":"Kızılordu'nun Nahçıvan'a girişi","gun":"28 Temmuz 1920","yer":"Nahçıvan","yer_id":"Nahçıvan","kisiler":"","d":"1919 başlarında bölgeye giren İngilizler Aras Cumhuriyeti'ni feshetmiş, aynı yılın yazında Nahçıvan'dan ayrılmıştı. TDV'nin Nahçıvan maddesine göre Kızılordu 28 Temmuz 1920'de Nahçıvan'a girerek yönetimi komünistlere verdi ve Nahçıvan Sovyet Sosyalist Cumhuriyeti kuruldu. Bölgenin statüsü 1921'de Kars'ta imzalanan antlaşmayla Azerbaycan'a bağlı özerk bir birim olarak belirlendi.","kaynak":"nahcivan"},{"onem":3,"dunya":1,"bolge_onem":1,"puan_s":"v2","kapsam":"ic","t":"1920-08-29","k":"kayip","etiket":["isgal","konu-askeri"],"b":"Uşak'ın Yunan işgali","gun":"29 Ağustos 1920","yer":"Uşak, Gediz","yer_id":"Uşak","kisiler":"","d":"Yunan ordusu, Ankara'nın tanımadığı Sevr Antlaşması'nı kabul ettirmek amacıyla ilerleyişini sürdürdü. TDV'nin Uşak ve Millî Mücadele maddelerine göre Gediz'den sonra 29 Ağustos 1920'de Uşak da işgal edildi. Mustafa Kemal Paşa şehirdeki Kuvâ-yi Milliye birliklerini bu işgalden yaklaşık bir ay önce denetlemişti.","kaynak":"usak · milli-mucadele"},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","kapsam":"ic","t":"1920-10-25","k":"kayip","etiket":["isgal","konu-askeri"],"b":"İnegöl ve Yenişehir'in Yunan işgali","gun":"25 Ekim 1920","yer":"İnegöl, Yenişehir","yer_id":"İnegöl","kisiler":"","d":"Bursa'daki Yunan birlikleri doğuya, Eskişehir yönüne doğru ilerlemeye başladı. TDV'nin Millî Mücadele maddesine göre 25 Ekim 1920'de İnegöl ve Yenişehir ele geçirildi. Yunan ilerleyişinin milis güçleriyle durdurulamayacağı anlaşılınca batı cephesi düzenli ordu esasına göre yeniden örgütlendi.","kaynak":"milli-mucadele"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","tur":"savas","kapsam":"ic","t":"1921-03-23","k":"savas","etiket":["savas","isgal","konu-askeri"],"b":"Yunan ordusunun ikinci taarruzu — Bilecik, Afyon ve Adapazarı'nın işgali","gun":"23-25 Mart 1921","yer":"Bilecik, Afyon, Adapazarı","yer_id":"Karahisâr-ı Sâhib (Afyon)","kisiler":"","d":"Birinci İnönü yenilgisinden sonra İzmir'e yeni kuvvetler çıkaran Yunan ordusu, Londra Konferansı'nın tanıdığı süre dolmadan yeniden taarruza geçti. TDV'nin Millî Mücadele maddesine göre Yunanlılar 23 Mart'ta Bilecik ve Afyon'u işgal etti. Kuzeyde Adapazarı da 25 Mart'ta Yunan işgaline uğradı.","kaynak":"milli-mucadele · adapazari"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1921-03-28","k":"siyaset","etiket":["diplomasi","konu-askeri","konu-diplomasi"],"b":"Türk kuvvetlerinin Batum'u boşaltması","gun":"28 Mart 1921","yer":"Batum","yer_id":"Batum","kisiler":"","d":"İngilizler Temmuz 1920'de Kafkasya'dan çekilirken Batum'u boşaltmış, şehre Gürcistan hükümeti el koymuştu. TDV'nin Batum maddesine göre 16 Mart 1921'de Sovyet Rusya ile imzalanan Moskova Antlaşması Batum'u Gürcistan'a bıraktı. Türk kuvvetleri şehri 28 Mart 1921'de boşalttı ve Batum, Gürcistan içinde kurulan Özerk Acara Cumhuriyeti'nin merkezi oldu.","kaynak":"batum"},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","tur":"savas","kapsam":"ic","t":"1921-04-07","k":"savas","etiket":["savas","kurtulus","konu-askeri"],"b":"Afyon'un geri alınışı — Aslıhanlar muharebeleri","gun":"7 Nisan 1921","yer":"Afyon, Aslıhanlar","yer_id":"Karahisâr-ı Sâhib (Afyon)","kisiler":"","d":"İkinci İnönü'de 1 Nisan'da durdurulan Yunan taarruzunun ardından güney cephesinde Afyon 7 Nisan'da geri alındı. TDV'nin Millî Mücadele maddesi bunu 'Aslıhanlar’da ağır yenilgiye uğratılarak 7 Nisan’da Afyon geri alındı' diye özetler; ancak askerî tarih çalışmaları Aslıhanlar-Dumlupınar çarpışmalarını Afyon'un boşaltılmasından sonra, 8-15 Nisan arasına koyar ve taktik üstünlüğün Yunan tarafında kaldığını yazar — iki anlatım birbirini tutmaz, ikisi de verildi. İnönü zaferi başta İstanbul olmak üzere bütün ülkede mitinglerle kutlandı.","kaynak":"milli-mucadele (TDV) · Uca (DergiPark article-file/1677265; Türk İstiklal Harbi 1966 s. 534, 574'e dayanarak Aslıhanlar 8-12, Dumlupınar 13-15 Nisan) · Kaya (DergiPark article-file/403536; Afyon tahliyesi, ATASE 1999)"},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1921-06-28","k":"kazanc","etiket":["savas","kurtulus","konu-askeri"],"b":"İzmit'in kurtuluşu — Adapazarı'nın ardından","gun":"28 Haziran 1921","yer":"İzmit, Adapazarı","yer_id":"İzmit","kisiler":"","d":"Mart 1921'de Yunan işgaline uğrayan Adapazarı, TDV'nin Adapazarı maddesine göre 21 Haziran'da geri alındı. TDV'nin İzmit maddesine göre 6 Temmuz 1920'de önce İngilizler, ardından Yunanlılar tarafından işgal edilen İzmit de 28 Haziran 1921'de kurtarıldı. Yunanlılar şehri terk ederken çarşı kesimini yaktı.","kaynak":"izmit · adapazari"},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","kapsam":"ic","t":"1921-07-05","k":"kazanc","etiket":["kurtulus","isgal","konu-askeri"],"b":"Muğla'nın İtalyan işgalinden kurtuluşu","gun":"5 Temmuz 1921","yer":"Muğla","yer_id":"Muğla","kisiler":"","d":"İtalya, Anadolu'daki işgal bölgesinden 1921 yazında çekilmeye başladı; Antalya'nın boşaltılması 1 Haziran'da başlamıştı. TDV'nin Muğla maddesine göre 23 Temmuz 1919'dan beri İtalyan işgalinde bulunan Muğla 5 Temmuz 1921'de kurtarıldı.","kaynak":"mugla"},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1921-07-20","k":"kayip","etiket":["savas","isgal","konu-askeri"],"b":"Eskişehir'in boşaltılması — Yunan ordusu Eskişehir, Kütahya ve Bilecik'e girdi","gun":"20-22 Temmuz 1921","yer":"Eskişehir, Kütahya, Bilecik","yer_id":"Eskişehir","kisiler":"Mustafa Kemal Paşa","d":"Kütahya-Eskişehir savaşlarında hazırlıksız yakalanan Türk ordusu, Mustafa Kemal Paşa'nın emriyle Sakarya'nın doğusuna çekildi. TDV maddelerine göre Yunanlılar 20 Temmuz 1921'de Eskişehir'e, 21 Temmuz'da Kütahya'ya, 22 Temmuz'da Bilecik'e girdi. Yunan Kralı Konstantinos 28 Temmuz'da Kütahya'da savaş konseyine başkanlık etti ve ordu Ankara yönünde taarruza hazırlandı.","kaynak":"eskisehir · kutahya · bilecik · milli-mucadele"},{"onem":5,"dunya":2,"bolge_onem":4,"puan_s":"v2","tur":"savas","kapsam":"ic","t":"1922-08-26","k":"savas","etiket":["savas","konu-askeri"],"b":"Büyük Taarruz başladı","gun":"26 Ağustos 1922","yer":"Afyon, Kocatepe","yer_id":"Karahisâr-ı Sâhib (Afyon)","kisiler":"Mustafa Kemal Paşa","d":"Sakarya'dan sonra bir yıl süren hazırlığın ardından Türk ordusu Afyon cephesinde genel taarruza geçti. TDV'nin Millî Mücadele ve Kütahya maddelerine göre Büyük Taarruz 26 Ağustos 1922 sabahı Afyon'dan başladı ve Yunan ordusunun direnişi kısa sürede kırıldı.","kaynak":"milli-mucadele · kutahya · usak"},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1922-08-27","k":"kazanc","etiket":["savas","kurtulus","konu-askeri"],"b":"Afyon'un kurtuluşu","gun":"27 Ağustos 1922","yer":"Afyon","yer_id":"Karahisâr-ı Sâhib (Afyon)","kisiler":"Mustafa Kemal Paşa","d":"Taarruzun ikinci gününde Yunan cephesi Afyon önlerinde yarıldı. TDV'nin Afyonkarahisar maddesine göre bizzat Atatürk'ün kumanda ettiği Büyük Taarruz sonunda Yunan kuvvetleri bozguna uğratıldı ve şehir 27 Ağustos 1922'de kurtarıldı. Bu gün Afyon'un kurtuluş günü olarak kutlanır.","kaynak":"afyonkarahisar"},{"onem":5,"dunya":2,"bolge_onem":4,"puan_s":"v2","tur":"savas","kapsam":"ic","t":"1922-08-30","k":"savas","etiket":["savas","kurtulus","konu-askeri"],"b":"Başkumandanlık Meydan Muharebesi — Kütahya'nın kurtuluşu","gun":"30 Ağustos 1922","yer":"Dumlupınar, Kütahya","yer_id":"Kütahya","kisiler":"Mustafa Kemal Paşa","d":"Yunan ordusunun ana kuvvetleri Afyon ile Dumlupınar arasında kuşatıldı. TDV'nin Millî Mücadele maddesine göre kuşatma harekâtı 30 Ağustos'ta Başkumandan Mustafa Kemal Paşa'nın bizzat yönettiği Başkumandanlık Muharebesi ile tamamlandı. TDV'nin Kütahya maddesine göre aynı gün bir süvari tümeni, çekilen Yunan kuvvetlerinin yakıp yıktığı Kütahya'yı kurtardı.","kaynak":"milli-mucadele · kutahya"},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1922-09-01","k":"kazanc","etiket":["savas","kurtulus","konu-askeri"],"b":"Uşak'ın kurtuluşu","gun":"1 Eylül 1922","yer":"Uşak","yer_id":"Uşak","kisiler":"","d":"Başkumandanlık Muharebesi'nden sonra Yunan ordusunun artıkları batıya, İzmir yönüne çekildi. TDV'nin Uşak maddesine göre 29 Ağustos 1920'den beri işgalde bulunan Uşak, millî kuvvetlerin şehre girişiyle 1 Eylül 1922'de kurtuldu. Çekilen işgal kuvvetlerinin çıkardığı yangında şehrin yaklaşık dörtte üçü yandı.","kaynak":"usak"},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1922-09-02","k":"kazanc","etiket":["savas","kurtulus","konu-askeri"],"b":"Eskişehir'in kurtuluşu","gun":"2 Eylül 1922","yer":"Eskişehir","yer_id":"Eskişehir","kisiler":"","d":"Büyük Taarruz'un kuzey kanadında Yunan kuvvetleri Eskişehir'i de bırakmak zorunda kaldı. TDV'nin Eskişehir maddesine göre 20 Temmuz 1921'den beri işgal altındaki şehir 30 Ağustos zaferinin ardından 2 Eylül 1922'de kurtarıldı. On üç aylık işgal sonunda çarşı kesimi yakılmış, şehir yarı yarıya harap olmuştu.","kaynak":"eskisehir"},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","kapsam":"ic","t":"1922-09-06","k":"kazanc","etiket":["savas","kurtulus","konu-askeri"],"b":"Bilecik'in kurtuluşu","gun":"6 Eylül 1922","yer":"Bilecik","yer_id":"Bilecik","kisiler":"","d":"TDV'nin Bilecik maddesine göre şehir Millî Mücadele sırasında üç kez Yunan işgaline uğradı; 22 Temmuz 1921'de başlayan üçüncü işgal 6 Eylül 1922'de sona erdi. Yunan kuvvetleri şehri boşaltırken çıkardıkları yangında evlerin, dükkânların ve hükümet konağının büyük kısmı yandı.","kaynak":"bilecik"},{"onem":3,"dunya":1,"bolge_onem":1,"puan_s":"v2","kapsam":"ic","t":"1922-09-07","k":"kazanc","etiket":["savas","kurtulus","konu-askeri"],"b":"Aydın'ın kurtuluşu","gun":"7 Eylül 1922","yer":"Aydın","yer_id":"Aydın","kisiler":"","d":"Türk ordusunun İzmir'e yaklaşmasıyla Menderes vadisindeki Yunan kuvvetleri de çekildi. TDV'nin Aydın maddesine göre şehir 7 Eylül 1922'de kısmen yıkılmış ve nüfusu çok azalmış hâlde Türk kuvvetleri tarafından kurtarıldı. Geri çekilen Yunanlılar şehrin büyük kısmını yakmıştı.","kaynak":"aydin"},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1922-09-11","k":"kazanc","etiket":["savas","kurtulus","konu-askeri"],"b":"Bursa'nın geri alınışı","gun":"10-11 Eylül 1922","yer":"Bursa","yer_id":"Bursa","kisiler":"","d":"İzmir'in kurtuluşundan sonra Türk ordusu kuzeyde Marmara kıyılarına doğru ilerledi. TDV'nin Bursa maddesine göre 8 Temmuz 1920'den beri Yunan işgalinde bulunan şehir 10-11 Eylül 1922'de geri alındı. Ordunun buradan Çanakkale'ye yürümesi İngilizleri telaşlandırdı ve Mudanya görüşmelerinin yolunu açtı.","kaynak":"bursa · milli-mucadele"},{"onem":4,"dunya":2,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1922-11-10","k":"kazanc","etiket":["kurtulus","antlasma","konu-askeri"],"b":"Doğu Trakya'nın teslim alınması — Kırklareli ve Tekirdağ","gun":"10-13 Kasım 1922","yer":"Kırklareli, Tekirdağ, Edirne","yer_id":"Kırklareli","kisiler":"Refet Paşa","d":"Mudanya Mütarekesi Doğu Trakya'nın Yunan ordusunca boşaltılıp Türkiye'ye teslimini öngörüyordu; Trakya'yı teslim almakla görevli Refet Paşa 19 Ekim'de İstanbul'a geldi. TDV'ye göre 26 Temmuz 1920'den beri işgal altındaki Kırklareli 10 Kasım 1922'de geri alındı, Tekirdağ da mütareke uyarınca 13 Kasım'da Türklere iade edildi. Böylece Doğu Trakya savaşılmadan Türk topraklarına katıldı.","kaynak":"kirklareli · tekirdag · milli-mucadele"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","tur":"isgal","kapsam":"ic","t":"1919-10-15","k":"isgal","etiket":["isgal","konu-askeri"],"b":"Garbî Trakya'da Fransız askerî idaresinin başlaması","gun":"15 Ekim 1919","yer":"Gümülcine, İskeçe, Dedeağaç (Alexandroupoli), Sofulu (Soufli), Ferecik (Feres), Távri","yer_id":"Gümülcine","kisiler":"","d":"Birinci Dünya Savaşı'nı kaybeden Bulgaristan'ın elindeki Batı Trakya, barış görüşmeleri sürerken İtilaf devletlerinin denetimine alındı. TDV'nin Batı Trakya maddesine göre bölge 15 Ekim 1919'da Fransız kuvvetlerince işgal edildi; Batı Trakya Müdâfaa-i Hukuk Cemiyeti bu dönemde merkezini Gümülcine'ye taşıdı. Fransız idaresi, San Remo kararıyla bölgenin Mayıs 1920'de Yunanistan'a bırakılmasına kadar sürdü.","kaynak":"bati-trakya"},{"onem":1,"dunya":1,"bolge_onem":1,"puan_s":"v2","kapsam":"ic","t":"1921-01-01","kesinlik":"yil","k":"kazanc","etiket":["kurtulus","isgal","konu-askeri"],"b":"Burdur'un İtalyan işgalinin sona ermesi (yıl)","gun":"1921 (gün bilinmiyor)","yer":"Burdur","yer_id":"Burdur","kisiler":"","d":"28 Haziran 1919'da İtalyanlarca işgal edilen Burdur, TDV'nin Burdur maddesine göre 1919-1921 yılları arasında kısa süreli bir İtalyan işgali yaşadı. Kaynak tahliyenin gününü vermiyor; haritada işgal 1921 yılının başında biter. İtalya Anadolu'daki işgal bölgesinden 1921 yazında tümüyle çekildi.","kaynak":"burdur · isparta"},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1557-04-02","k":"fetih","etiket":["toprak-kazanc","konu-askeri"],"b":"Özdemir Paşa'nın Masavva' limanını alması","gun":"2 Cemâziyelâhir 964 (2 Nisan 1557)","yer":"Masavva, Arkîko, Dahlak (Dehlek)","yer_id":"Masavva","kisiler":"Özdemir Paşa","d":"Habeş Eyaleti'nin beylerbeyi Özdemir Paşa, Dehlek adalarını ele geçirdikten sonra karşı kıyıdaki Masavva' şehrini 2 Nisan 1557'de aldı; ardından Arkîko da Osmanlı idaresine girdi. Böylece Habeşistan'ın Kızıldeniz'e açılan başlıca limanı Osmanlı'nın eline geçti.","kaynak":"masavva · habes-eyaleti"},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","kapsam":"dis","bolge":1,"t":"1793-01-31","k":"siyaset","etiket":["siyaset","konu-siyasi","konu-diplomasi"],"b":"Nice Kontluğu'nun Fransa'ya katılması","gun":"31 Ocak 1793","yer":"Nice","yer_id":"Nice","kisiler":"","d":"Savoy'un Kasım 1792'de katılmasından sonra Fransız Ulusal Konvansiyonu, Sardinya Krallığı'na ait Nice Kontluğu'nun Fransa'ya katılmasını 31 Ocak 1793'te onayladı; bölge Alpes-Maritimes departmanı oldu. Nice, Napolyon'un yenilgisinden sonra 30 Mayıs 1814 tarihli I. Paris Antlaşması'yla Sardinya'ya geri döndü.","kaynak":"Digithèque MJP (d1793nice, traites/1814paris)"},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1922-04-29","k":"kazanc","etiket":["kurtulus","isgal","konu-askeri"],"b":"İtalyan birliklerinin Marmaris ve Kuşadası'ndan çekilişi","gun":"24-29 Nisan 1922","yer":"Marmaris, Kuşadası","yer_id":"Marmaris","kisiler":"","d":"Mayıs 1919'dan beri güneybatı Anadolu kıyılarında bulunan İtalyanlar, Ankara Hükümeti ile yakınlaşmanın ardından işgal bölgesini adım adım boşalttı. Antalya ve Bodrum 1921 yazında boşaltılmıştı; son İtalyan birlikleri Nisan 1922'nin sonunda Kuşadası ve Marmaris'ten de ayrıldı.","kaynak":"Çelebi, Belleten 233 (1998) · ATAM Dergisi"},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"dis","bolge":2,"t":"1442-01-16","k":"siyaset","etiket":["siyaset","konu-siyasi"],"b":"Müşa'şa'îler Havîza'ya yerleşti — Huzistan'da Müşa'şa' idaresi başladı","gun":"4 Ramazan 845 / 16 Ocak 1442","yer":"Havîza","yer_id":"Havîza","kisiler":"Muhammed b. Felâh","d":"Mehdîlik iddiasıyla ortaya çıkan Muhammed b. Felâh, Meâdî aşiretleri arasında tutunduktan sonra ertesi yıl Timurlular'ın denetimindeki Havîza'ya yerleşmeyi başardı. Şehir, Huzistan'da hüküm sürecek Müşa'şa'î hânedanının merkezi oldu.","kaynak":"musasalar"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"dis","bolge":3,"t":"1508-05-02","k":"siyaset","etiket":["siyaset","konu-siyasi"],"b":"Şah İsmâil Havîza'yı bağladı — Müşa'şa'îler Safevî'ye tâbi valiler oldu","gun":"914 (1508-1509)","yer":"Havîza","yer_id":"Havîza","kisiler":"Şah İsmâil","d":"Şah İsmâil, zındıklıkla itham ettiği Müşa'şa' hânedanı üyelerinden bazılarını öldürttü ve Havîza bölgesini kendi idaresine bağladı. Müşa'şa' reisleri bundan sonra varlıklarını Safevîler'e tâbi valiler olarak sürdürdüler.","kaynak":"musasalar"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1534-01-01","k":"fetih","etiket":["toprak-kazanc","konu-askeri"],"b":"Pasin, Şüregel ve Oltu kaleleri Safevîlerden alındı — Erzurum-Kars arası","gun":"940 (1533-34)","yer":"Pasinler (Hasankale), Şüregel, Oltu","yer_id":"Pasinler (Hasankale)","kisiler":"Kanûnî Sultan Süleyman","d":"Kanûnî Sultan Süleyman'ın Irakeyn Seferi sırasında Erzurum ile Kars arasındaki Pasin, Şüregel ve Oltu kaleleri Safevîlerden alındı.","kaynak":"kars"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1918-03-12","k":"kazanc","etiket":["toprak-kazanc","savas","konu-askeri"],"b":"Kâzım Karabekir'in kış harekâtı: Erzurum ile birlikte Hasankale (Pasinler) geri alındı","gun":"12 Mart 1918 (Erzurum'un günü)","yer":"Pasinler (Hasankale), Erzurum","yer_id":"Pasinler (Hasankale)","kisiler":"Kâzım Karabekir","d":"Rus ordusunun çözülmesinden sonra doğuda harekâta geçen Kâzım Karabekir Paşa kumandasındaki Osmanlı kuvvetleri ağır kış şartlarına rağmen Erzincan'ı, Erzurum'u ve Erzurum'un doğusundaki Hasankale'yi geri aldı; ilerleyiş 25 Nisan 1918'de Kars'a uzandı.","kaynak":"kazim-karabekir · erzurum"},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1917-01-09","k":"kayip","etiket":["toprak-kayip","savas","konu-askeri"],"b":"Refah çarpışması — İngiliz-Anzak süvarisi Mağrunteyn mevzilerini ve Refah'ı aldı","gun":"9 Ocak 1917","yer":"Refah","yer_id":"Refah","kisiler":"","d":"Sînâ'yı geçen Mısır Seferî Kuvveti'nin Anzak Atlı Tümeni, İmparatorluk Deve Kolordusu Tugayı ve bir İngiliz yeomanry tugayı, Refah'ın bir kilometre kadar güneyindeki Mağrunteyn'de tabyalarla tutulan Osmanlı mevziine saldırdı. Güç bir çarpışmadan sonra Yeni Zelandalılar ile deve birliklerinin yarması Osmanlı savunmasını çökertti; mevzi ve yakınındaki Refah ele geçirildi ve İngiliz kuvvetleri Filistin sınırına ulaştı.","kaynak":"Australian War Memorial (awm.gov.au/articles/blog/gateway-to-palestine)"}];

