// data/olaylar_p0058.js — paketle.py İNCELTTİ: ic_not* alanları yayına gitmez (kaynak dosya değişmedi)
window.OLAYLAR_P0058 = [{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","bolge":3,"t":"1339-01-01","kesinlik":"yil","k":"fetih","kapsam":"dis","etiket":["toprak-kazanc","konu-siyasi"],"b":"Eretna, Tokat, Kayseri ve Samsun yörelerini kendisine bağladı","gun":"1339 (ay ve gün kaynakta yok)","yer":"Kayseri, Tokat, Samsun yöreleri; Zamantı (Pınarbaşı)","yer_id":"Kayseri","kisiler":"Emîr Eretna","d":"İlhanlı valisi olarak Anadolu'da güç kazanan Emîr Eretna, Memlûk Sultanı en-Nâsır Muhammed'in desteğini yeniden kazandıktan sonra 1339'da sınırlarını genişletti ve Tokat, Kayseri ile Samsun yörelerini kendisine bağladı. Kayseri'nin doğusundaki Zamantı yöresi de bu dönemde Eretna idaresine girdi. Beylik, 1341'de en-Nâsır'ın ölümüyle bağımsızlığını ilan etti.","kaynak":"Abdullah Kaya, 'Dulkadirli Beyliği'nin Eratnalılar ile Münasebetleri', MKÜ SBE Dergisi 11(25), 2014, s. 89 · eretnaogullari"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","bolge":3,"t":"1360-01-01","kesinlik":"yil","k":"fetih","kapsam":"dis","etiket":["toprak-kazanc","konu-siyasi"],"b":"Dulkadirli Halil Bey sınırlarını Zamantı'ya kadar genişletti","gun":"1360 (ay ve gün kaynakta yok)","yer":"Zamantı (Pınarbaşı), Kayseri'nin doğusu","yer_id":"Zamantı (Pınarbaşı)","kisiler":"Halil Bey (Dulkadiroğlu), Ömer Bey","d":"Eretna Beyliği'nin başına küçük yaşta Mehmed Bey'in geçmesiyle zayıflayan Eretna topraklarına güneyden Türkmen akınları arttı. 1360'ta Türkmen reislerinden Ömer Bey Malatya'yı alırken Dulkadiroğlu Halil Bey de beyliğinin sınırlarını Kayseri'nin doğusundaki Zamantı'ya kadar genişletti. Böylece Elbistan ile Kayseri arasındaki Zamantı yöresi Dulkadiroğulları'nın eline geçti ve beylik 1515'teki Osmanlı ilhakına kadar bu bölgeyi elinde tuttu.","kaynak":"dulkadirogullari · Kaya 2014 (MKÜ SBE Dergisi 11/25), s. 90, 92"},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","tur":"savas","t":"1394-01-01","kesinlik":"yil","k":"savas","kapsam":"ic","etiket":["savas","konu-askeri"],"b":"Yıldırım Bayezid İstanbul'u yeniden sıkı bir kuşatma altına aldı","gun":"1394 ilkbaharı (ay ve gün kaynakta yok)","yer":"İstanbul","yer_id":"İstanbul","kisiler":"Yıldırım Bayezid, II. Manuel","d":"1391'den beri aralıklarla abluka altında tutulan İstanbul, 1394 ilkbaharında Yıldırım Bayezid tarafından yeniden sıkı bir kuşatmaya alındı. 1371'den beri Osmanlı'ya haraç ödeyen ve askerî yardım gönderen Bizans ile ilişki böylece açık düşmanlığa döndü. Kuşatma, Timur tehlikesinin belirmesi ve 1402 Ankara Savaşı'yla kaldırıldı.","kaynak":"bayezid-i · bizans"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","tur":"antlasma","t":"1424-02-22","k":"antlasma","kapsam":"ic","etiket":["antlasma","diplomasi","konu-diplomasi"],"b":"II. Murad ile Bizans barışı — Bizans yeniden haraç ödemeyi kabul etti","gun":"22 Şubat 1424 (21 Rebîülevvel 827)","yer":"İstanbul","yer_id":"İstanbul","kisiler":"II. Murad, II. Manuel, VIII. Ioannes","d":"Düzmece Mustafa'yı destekleyen Bizans'a karşı 1422'de İstanbul'u kuşatan II. Murad, 22 Şubat 1424'te Bizans imparatoruyla barış antlaşması imzaladı. Bizans bu antlaşmayla yeniden Osmanlı'ya haraç ödemeyi kabul etti ve Silivri ile Terkos hisarları hariç Marmara, Ege ve Karadeniz kıyılarında 1402'den sonra aldığı yerleri geri vermeyi kabul etti; 1403'te Emîr Süleyman'la yaptığı antlaşmayla kurtulduğu yıllık haraç böylece geri döndü. Bizans bu durumunu 1453'te İstanbul'un fethine kadar sürdürdü.","kaynak":"murad-ii · bizans"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1514-10-23","k":"fetih","kapsam":"ic","etiket":["toprak-kazanc","savas","konu-askeri"],"b":"Bayburt ve Kiğı kaleleri Safevîlerden teslim alındı — Erzincan ile Bayburt Bıyıklı Mehmed Bey'e verildi","gun":"Ekim 1514 (Bayburt'un alınışı; gün kaynakta yok) · 23 Ekim 1514 (beylerbeyilik tevcihi)","yer":"Bayburt, Kiğı, Erzincan","yer_id":"Bayburt","kisiler":"Yavuz Sultan Selim, Bıyıklı Mehmed Bey (Paşa), Mustafa Bey (Yanya sancak beyi), Kara Maksûd-i Sultânî","d":"Çaldıran zaferinden sonra Tebriz'den dönen Yavuz Sultan Selim ordugâhındayken Bayburt ve Kiğı kalelerinin teslim alındığı haberleri geldi. Trabzon sancak beyi Bıyıklı Mehmed Bey ile Yanya sancak beyi Mustafa Bey, Şah İsmâil'in emîrlerinden Kara Maksûd-i Sultânî'nin savunduğu Bayburt'u Ekim 1514'te aldı. Savaşsız Osmanlı hâkimiyetine giren Erzincan, Bayburt ile birlikte 23 Ekim 1514'te beylerbeyilik olarak Bıyıklı Mehmed Bey'e verildi ve Bayburt bir sancak merkezi hâline getirildi.","kaynak":"selim-i · bayburt · erzincan"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1514-11-24","k":"diger","kapsam":"ic","etiket":["savas","konu-askeri"],"b":"Yavuz Sultan Selim Tebriz seferinden Amasya'ya döndü ve kışı orada geçirdi","gun":"24 Kasım 1514 (gün yalnız Remzi Kılıç'ta; TDV yalnız 'Amasya'ya döndü' der)","yer":"Amasya, Niksar","yer_id":"Amasya","kisiler":"Yavuz Sultan Selim","d":"Tebriz'de dokuz gün kalan Yavuz Sultan Selim, yiyecek sıkıntısı ve askerin isteksizliği yüzünden kışı İran'da geçirmekten vazgeçti ve Kars ile Bayburt üzerinden geri döndü. Niksar'da Ramazan Bayramı'nı geçiren padişah Amasya'ya ulaşarak kışı burada geçirdi. Ertesi yıl yeniden Safevîler üzerine yürümek niyetindeydi; Amasya'da yeniçerilerin İstanbul'a dönme baskısı başladı, sefer 1515 baharında Kemah'ın fethiyle sürdü.","kaynak":"selim-i · caldiran-savasi"}];

