window.OLAYLAR_P0059 = [{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","tur":"isyan","kapsam":"ic","t":"1594-11-13","k":"isyan","etiket":["isyan","savas","siyaset","konu-isyan","konu-siyasi","konu-askeri"],"b":"Eflak, Boğdan ve Erdel Osmanlı'ya karşı birlikte ayaklandı","gun":"13 Kasım 1594","yer":"Eflak ve Boğdan (Erdel'in desteğiyle)","yer_id":"Bükreş","kisiler":"Mihai Viteazul, Aron Tiran","d":"1594 ortasında Tuna'nın kuzeyindeki üç voyvodalık — Eflak, Boğdan ve Erdel — Osmanlı'ya karşı ortak hareket etmeyi kararlaştırdı. Boğdan voyvodası Aron Tiran, Avusturya İmparatoru ile Papa VIII. Clemens'in kurduğu Kutsal İttifak'a katılıp kendini Erdel Prensliği'ne tâbi kıldı; Eflak voyvodası Mihai Viteazul ağır vergi yükünden duyduğu hoşnutsuzlukla harekete katıldı. 13 Kasım 1594'te Eflak ve Boğdan'da Osmanlı yönetimine karşı eş zamanlı ayaklanmalar başladı ve Erdel'in desteğiyle hareket Tuna'nın güneyine, Osmanlı topraklarına doğru taştı. TDV İslâm Ansiklopedisi'ne göre bu üçlü ittifak, aynı yıllarda süren Osmanlı-Habsburg Uzun Harbi'nin (1593-1606) kuzey cephesini açtı.","kaynak":"eflak","duygu":["⚔","🏛"]}];

